arguments.command:
mkdir -p /app/bin /app/out; cat > /app/bin/hourly.py <<'EOF'
import sys, os, re, json, math
from datetime import datetime, timezone

QS = ["temp", "rh", "pres", "wspd", "wdir", "rain"]
RANGE = {"temp": (-50, 60), "rh": (0, 100), "pres": (870, 1085),
         "wspd": (0, 60), "wdir": (0, 360), "rain": (0, 5000)}
CONV = {
    ("temp", "degC"): lambda v: v,
    ("temp", "degF"): lambda v: (v - 32) * 5 / 9,
    ("temp", "K"): lambda v: v - 273.15,
    ("rh", "pct"): lambda v: v,
    ("rh", "frac"): lambda v: v * 100,
    ("pres", "hPa"): lambda v: v,
    ("pres", "kPa"): lambda v: v * 10,
    ("pres", "inHg"): lambda v: v * 33.8638866667,
    ("pres", "mmHg"): lambda v: v * 1.33322387415,
    ("wspd", "ms"): lambda v: v,
    ("wspd", "kmh"): lambda v: v / 3.6,
    ("wspd", "kn"): lambda v: v * 1852 / 3600,
    ("wspd", "mph"): lambda v: v * 0.44704,
    ("wdir", "deg"): lambda v: v,
    ("rain", "mm"): lambda v: v,
}
DIRRE = re.compile(r"^#\s*([a-z]+)\s*:(.*)$")
MISSING = re.compile(r"^-9999(\.0*)?$")


def conv_fn(q, unit):
    if (q, unit) in CONV:
        return CONV[(q, unit)]
    if q == "rain" and unit.startswith("tips:"):
        s = float(unit[5:])
        return lambda v: v * s
    return lambda v: v


def epoch(s):
    s = s.strip().replace("T", " ")
    d = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
    return int(d.replace(tzinfo=timezone.utc).timestamp())


def parse_tz(s):
    s = s.strip()
    if s == "Z":
        return 0
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return sign * (int(h) * 3600 + int(m) * 60)


def is_missing(f):
    f = f.strip()
    return f == "" or f == "---" or f.lower() == "nan" or bool(MISSING.match(f))


def read_file(path):
    with open(path, "rb") as fh:
        text = fh.read().decode("utf-8-sig")
    hdr = {}
    rows = []  # (logger_local_epoch, {q: value})
    syncs = []  # (logger_local_epoch, ref_epoch)
    cols = None
    units = {}
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip():
            continue
        if line.startswith("#"):
            m = DIRRE.match(line)
            if not m:
                continue
            k, v = m.group(1), m.group(2).strip()
            if k in ("station", "upload", "interval", "tz"):
                hdr[k] = v
            elif k == "columns":
                cols = [c.strip() for c in v.split(",")]
                if "columns" not in hdr:
                    hdr["columns"] = True
            elif k == "units":
                for p in v.split():
                    if "=" in p:
                        a, b = p.split("=", 1)
                        units[a] = b
            elif k == "sync":
                lg = ref = None
                for p in v.split():
                    if p.startswith("logger="):
                        lg = p[7:]
                    elif p.startswith("ref="):
                        ref = p[4:]
                if lg and ref:
                    syncs.append((epoch(lg), epoch(ref.rstrip("Z"))))
                # logger part may contain a space: handle "logger=DATE TIME"
                else:
                    m2 = re.search(r"logger=(\S+(?: \d\d:\d\d:\d\d)?)", v)
                    m3 = re.search(r"ref=(\S+)", v)
                    if m2 and m3:
                        syncs.append((epoch(m2.group(1)), epoch(m3.group(1).rstrip("Z"))))
            continue
        fields = [f.strip() for f in line.split(",")]
        row = {}
        t = None
        for c, f in zip(cols, fields):
            if c == "time":
                t = epoch(f)
            elif c in RANGE:
                if is_missing(f):
                    continue
                try:
                    v = conv_fn(c, units.get(c, {"temp": "degC", "rh": "pct", "pres": "hPa", "wspd": "ms", "wdir": "deg", "rain": "mm"}[c]))(float(f))
                except ValueError:
                    continue
                lo, hi = RANGE[c]
                if lo <= v <= hi:
                    row[c] = v
        rows.append((t, row, [c for c in cols if c in RANGE]))
    return hdr, rows, syncs


def main(indir, outfile):
    stations = {}
    for name in sorted(os.listdir(indir)):
        p = os.path.join(indir, name)
        if not name.endswith(".log") or not os.path.isfile(p):
            continue
        hdr, rows, syncs = read_file(p)
        if "station" not in hdr:
            continue
        tz = parse_tz(hdr.get("tz", "Z"))
        up = int(hdr.get("upload", 0))
        st = stations.setdefault(hdr["station"], {"interval": None, "rows": {}, "syncs": {}, "cols": set()})
        if "interval" in hdr:
            st["interval"] = int(float(hdr["interval"]))
        for t, row, cs in rows:
            u = t - tz
            old = st["rows"].get(u)
            if old is None or old[0] < up:
                st["rows"][u] = (up, row)
            st["cols"].update(cs)
        for lg, ref in syncs:
            u = lg - tz
            old = st["syncs"].get(u)
            if old is None or old[0] < up:
                st["syncs"][u] = (up, ref - u)

    out = []
    for sid in sorted(stations):
        st = stations[sid]
        if not st["rows"]:
            continue
        interval = st["interval"]
        sp = sorted((u, o[1]) for u, o in st["syncs"].items())

        def offset(t):
            if not sp:
                return 0
            if t <= sp[0][0]:
                return sp[0][1]
            if t >= sp[-1][0]:
                return sp[-1][1]
            lo, hi = 0, len(sp) - 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if sp[mid][0] <= t:
                    lo = mid
                else:
                    hi = mid
            t1, o1 = sp[lo]
            t2, o2 = sp[hi]
            if t == t1:
                return o1
            return o1 + ((o2 - o1) * (t - t1)) // (t2 - t1)

        recs = []
        for u, (up, row) in st["rows"].items():
            recs.append((u + offset(u), u, row))
        recs.sort(key=lambda x: (x[0], x[1]))
        hours = {}
        for c, u, row in recs:
            h = -((-c) // 3600) * 3600
            hours.setdefault(h, []).append((c, row))
        first, last = min(hours), max(hours)
        expected = 3600 / interval
        # rain increments
        incr = {}
        prev = None
        for c, u, row in recs:
            if "rain" in row:
                r = row["rain"]
                if prev is not None and (c - prev[0]) * 2 <= 5 * interval:
                    incr[id(row)] = r - prev[1] if r >= prev[1] else r
                prev = (c, r)
        hl = []
        for h in range(first, last + 1, 3600):
            ent = {"hour": datetime.fromtimestamp(h, timezone.utc).strftime("%Y-%m-%dT%H:00:00Z")}
            rs = hours.get(h, [])
            for q in QS:
                vals = [row[q] for c, row in rs if q in row]
                n = len(vals)
                v = None
                if n and n * 4 >= expected * 3:
                    if q == "rain":
                        v = math.fsum(incr.get(id(row), 0) for c, row in rs if q in row)
                    elif q == "wdir":
                        sx = sy = 0.0
                        k = 0
                        for c, row in rs:
                            if "wdir" in row and row.get("wspd", 0) > 0:
                                a = math.radians(row["wdir"])
                                sx += math.sin(a)
                                sy += math.cos(a)
                                k += 1
                        if k:
                            v = math.degrees(math.atan2(sx, sy)) % 360
                    else:
                        v = math.fsum(vals) / n
                if v is not None:
                    v = round(v, 2)
                    if v >= 360 or v == 0:
                        v = 0.0 if v >= 360 or v == 0 else v
                ent[q] = {"value": v, "n": n}
            hl.append(ent)
        out.append({"station": sid, "interval_s": interval, "hours": hl})
    with open(outfile, "w") as f:
        json.dump({"stations": out}, f)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
